def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]

    opp_c = sum(1 for b in opp_actions if b == 'C')
    my_c = sum(1 for a in my_actions if a == 'C')
    opp_d = n - opp_c
    my_d = n - my_c
    my_last, opp_last = history[-1]

    r5_c = sum(1 for b in opp_actions[-5:] if b == 'C')
    r10_c = sum(1 for b in opp_actions[-10:] if b == 'C')
    r20_c = sum(1 for b in opp_actions[-20:] if b == 'C')
    n5 = 5 if n >= 5 else n
    n10 = 10 if n >= 10 else n
    n20 = 20 if n >= 20 else n

    opp_pct = opp_c * 100 // n
    r5_pct = r5_c * 100 // n5
    r10_pct = r10_c * 100 // n10
    r20_pct = r20_c * 100 // n20

    opp_d_streak = 0
    for b in reversed(opp_actions):
        if b == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for b in reversed(opp_actions):
        if b == 'C':
            opp_c_streak += 1
        else:
            break

    my_d_streak = 0
    for a in reversed(my_actions):
        if a == 'D':
            my_d_streak += 1
        else:
            break

    pc_num = 0
    pc_den = 0
    pd_num = 0
    pd_den = 0
    w = n - 1
    if w > 25:
        w = 25
    if w > 0:
        start = n - 1 - w
        for i in range(start, n - 1):
            prev_my = my_actions[i]
            next_opp = opp_actions[i + 1]
            if prev_my == 'C':
                pc_den += 1
                if next_opp == 'C':
                    pc_num += 1
            else:
                pd_den += 1
                if next_opp == 'C':
                    pd_num += 1

    pc = pc_num / pc_den if pc_den >= 2 else opp_c / n
    pd = pd_num / pd_den if pd_den >= 2 else opp_c / n

    forgiving = pd_den >= 2 and pd >= 0.65 and (opp_pct >= 70 or r10_pct >= 80)
    cooperation_gain = (
        pc_den >= 2 and pc >= 0.55 and pc - pd >= 0.15 and
        (opp_pct >= 55 or r10_pct >= 60)
    )

    if n < 4:
        return 'C'

    if opp_c == 0:
        return 'D'
    if r5_pct == 0 and n >= 5:
        return 'D'
    if opp_d_streak >= 5 and opp_pct < 75:
        return 'D'
    if opp_pct <= 30 and r10_pct <= 50:
        return 'D'
    if opp_pct <= 45 and r5_pct <= 40 and not cooperation_gain:
        return 'D'

    if opp_c == n:
        if n >= 94 and pd_den >= 1 and pd_num == pd_den:
            return 'D'
        if (n == 92 or n == 96) and rng.random() < 0.45:
            return 'D'

    if opp_last == 'D':
        caused = n >= 2 and history[-2][0] == 'D'
        if caused and cooperation_gain and opp_pct >= 55:
            return 'C'
        if opp_d_streak >= 3 and opp_pct < 85:
            return 'D'
        if opp_pct >= 85 and r5_pct >= 60 and opp_d_streak == 1:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        return 'D'

    if forgiving and (opp_pct >= 85 or r5_pct >= 80 or pd >= 0.85):
        if n >= 90 or my_d_streak >= 1 or r10_pct >= 90:
            return 'D'

    if cooperation_gain and opp_pct >= 65:
        return 'C'

    if my_last == 'D':
        return 'C'

    if opp_pct <= 40:
        return 'D'

    if opp_pct <= 55:
        return 'C' if rng.random() < 0.35 else 'D'

    return 'C'
